import{_ as n,l as s,o as e,c as o,v as t,p as l,x as r,d as _,i as p,S as h}from"./chunks/framework.InCnrqk-.js";const b=JSON.parse('{"title":"菲涅尔反射与透射","description":"","frontmatter":{"title":"菲涅尔反射与透射","date":"2026-09-10T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/fresnel-coefficients.md","filePath":"litho/fresnel-coefficients.md","lastUpdated":1789023840000}'),c={name:"litho/fresnel-coefficients.md"};function d(f,a,E,m,A,B){const i=s("Mermaid");return e(),o("div",null,[a[1]||(a[1]=t('<h1 id="菲涅尔反射与透射" tabindex="-1">菲涅尔反射与透射 <a class="header-anchor" href="#菲涅尔反射与透射" aria-label="Permalink to &quot;菲涅尔反射与透射&quot;">​</a></h1><div class="epigraph"><p>平面波在两种均匀介质的平面界面上分解为 s 与 p；反射与透射振幅由两侧折射率与入射角决定，不是经验贴图。</p><footer>—— 据 Born &amp; Wolf, Principles of Optics 第 1.5 节对 Fresnel 公式的整理</footer></div><p><a href="/litho/polarization-states">上一课</a>把电场写成两个正交分量，并指出界面上要改写成 s 与 p。本课不重讲椭圆率。缺口是：界面两侧场如何匹配？反射波与透射波的振幅比是多少？后课薄膜干涉、抗反射膜与多层掩模，都建立在菲涅尔系数上。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p><a href="/litho/plane-wave-k">平面波与波矢</a>已经给出切向 \\(\\mathbf{k}\\) 连续，从而 \\(n_1\\sin\\theta_i=n_2\\sin\\theta_t\\)。振幅比尚未写出。没有 \\(r_s\\)、\\(r_p\\)、\\(t_s\\)、\\(t_p\\)，无法解释垂直入射反射率 \\((n_1-n_2)^2/(n_1+n_2)^2\\)，也无法把多层里的多次反射连乘起来。缺口是麦克斯韦在平面界面上的解析解，不是再定义一次偏振。</p><h3 id="能量流与振幅比不是同一个数" tabindex="-1">能量流与振幅比不是同一个数 <a class="header-anchor" href="#能量流与振幅比不是同一个数" aria-label="Permalink to &quot;能量流与振幅比不是同一个数&quot;">​</a></h3><p>振幅系数 \\(r\\)、\\(t\\) 是场的比值；功率反射率 \\(R=|r|^2\\)（对无吸收、同侧介质）。透射侧折射率不同时，功率透射率还要乘阻抗因子，不能把 \\(|t|^2\\) 直接叫「透过的能量份额」。后课膜系若只盯振幅相位，干涉条纹对；谈剂量与吸收时必须换成功率。</p><p><span class="marginnote">s：\\(\\mathbf{E}\\) 垂直入射面；p：\\(\\mathbf{E}\\) 在入射面内。光刻文献里 TE/TM 常与 s/p 互换，读公式时先核对「相对哪一个平面」。本课介质取实折射率。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>介质 1（\\(n_1\\)）到介质 2（\\(n_2\\)），入射角 \\(\\theta_i\\)，折射角 \\(\\theta_t\\)。菲涅尔振幅系数（Born &amp; Wolf 记号）：</p> \\[r_s=\\frac{n_1\\cos\\theta_i-n_2\\cos\\theta_t}{n_1\\cos\\theta_i+n_2\\cos\\theta_t},\\quad r_p=\\frac{n_2\\cos\\theta_i-n_1\\cos\\theta_t}{n_2\\cos\\theta_i+n_1\\cos\\theta_t}. \\]<p>\\(t_s\\)、\\(t_p\\) 由切向场连续确定。垂直入射时 \\(r_s=r_p=(n_1-n_2)/(n_1+n_2)\\)，\\(r\\lt 0\\) 表示相对入射电场有 \\(\\pi\\) 相位跳——<a href="/litho/thin-film-interference">薄膜干涉</a> 必须把这「半波损失」与几何光程差一起算。反射率 \\(R_s=|r_s|^2\\)，\\(R_p=|r_p|^2\\)。\\(R_s\\) 与 \\(R_p\\) 一般不相等，只在正入射重合。</p>',12)),(e(),l(h,null,{default:r(()=>[p(i,{id:"mermaid-32",class:"mermaid",graph:"flowchart%20TD%0A%20%20INC%5B%22%E5%85%A5%E5%B0%84%E5%B9%B3%E9%9D%A2%E6%B3%A2%22%5D%20--%3E%20SPLIT%5B%22%E5%88%86%E8%A7%A3%20s%20%2F%20p%22%5D%0A%20%20SPLIT%20--%3E%20SN%5B%22%E6%96%AF%E6%B6%85%E5%B0%94%E5%AE%9A%E5%BE%8B%22%5D%0A%20%20SN%20--%3E%20FR%5B%22%E8%8F%B2%E6%B6%85%E5%B0%94%20r%2C%20t%22%5D%0A%20%20FR%20--%3E%20MULTI%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9A%E5%A4%9A%E5%B1%82%E4%B8%8E%E7%89%B9%E6%AE%8A%E8%A7%92%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[_(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>边界条件：无自由面电荷与面电流时，切向 \\(\\mathbf{E}\\)、切向 \\(\\mathbf{H}\\) 连续。菲涅尔公式是这组条件对平面波的解，不是拟合。光刻里晶圆上抗蚀剂/空气、浸没液体/末片玻璃、多层掩模的每一层界面，都要叠乘这些系数。相位与振幅一起走：只改 \\(|r|\\)、忘掉 \\(\\arg r\\)，条纹亮暗会整层翻错。</p><p>高 NA 下边缘光线入射角大，\\(R_s\\neq R_p\\)，矢量效应从界面就开始。标量模型用一个有效 \\(U\\) 代替，等于假定两种偏振可平均；本课程末课再收这条近似的适用边界。p 偏振在某一入射角反射为零，全内反射时透射波变成倏逝——那是下一课 <a href="/litho/brewster-tir">布鲁斯特角与全内反射</a> 的两个特殊角。</p><p>多层膜不是新的麦克斯韦，只是把本课的 \\(r\\)、\\(t\\) 与膜内传播因子 \\(e^{ik_z d}\\) 串成矩阵。单层已经能看出：改变 \\(d\\) 就是改变两界面回波的相位差。下一课把这一观察写成反射率振荡；本课停在单界面系数。吸收与金属色散会让 \\(n\\) 变复数，\\(r\\) 的模不再单独由角度公式的实数形式给出，那是材料课，本课系数保持实 \\(n\\)。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课假定理想平面、无限宽、无吸收。曲率半径远大于波长时局部仍可用。粗糙度、散射与去偏振不在本课。吸收介质用复折射率 \\(n+i\\kappa\\)，系数变复数；EUV 强吸收层留给后课材料，本课不把 \\(\\kappa\\) 写进公式。也不推导倏逝波的衰减长度。</p><p>后课默认：单界面用菲涅尔 \\(r\\)、\\(t\\)；多层先把每一界面的系数与膜内传播相位串起来。下一课只补两个特殊角，不重写一般公式。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>s/p 菲涅尔系数由两侧 \\(n\\) 与入射角决定；斯涅尔定律约束折射角。</li><li>垂直入射反射率只与折射率差有关；\\(r\\lt 0\\) 带来相位跳，影响干涉。</li><li>振幅比不是功率比；跨介质时功率还要乘阻抗因子。</li><li>多层膜 = 界面系数与传播相位连乘，下一课先看特殊角。</li><li>出处：Born &amp; Wolf, <em>Principles of Optics</em>；Jackson, <em>Classical Electrodynamics</em> 第 7 章。</li></ul>',9))])}const T=n(c,[["render",d]]);export{b as __pageData,T as default};
